/* Sign Korean: an offline, local-only interactive design prototype. */
(() => {
  'use strict';
  const D = window.DATA;
  const KEY = 'sign-korean-design-v1';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clone = value => JSON.parse(JSON.stringify(value));
  const today = () => new Intl.DateTimeFormat('en-CA', {timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const uid = () => 'id-' + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
  const dates = (start,end) => { const out=[]; const first=new Date(start+'T12:00:00Z'), last=new Date(end+'T12:00:00Z'); if(!Number.isFinite(+first)||!Number.isFinite(+last)) return out; for(let d=first;d<=last && out.length<15;d=new Date(+d+86400000)) out.push(d.toISOString().slice(0,10)); return out; };
  const dateLabel = date => new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',weekday:'short',timeZone:'Asia/Seoul'});
  const makeDay = () => ({start:'09:00',origin:null,stops:[]});
  function fresh() { return {onboard:false,guideStep:0,progress:{},saved:{},session:null,trips:[],paid:false,everPaid:false}; }
  const FREE_BOOKMARK_LIMIT = 5;   // FR27
  let state=fresh(), storageWarning=false;
  try { const saved=localStorage.getItem(KEY); if(saved) state={...fresh(),...JSON.parse(saved)}; } catch (_) { storageWarning=true; }
  let route={name:state.onboard?'explore':'guide',step:state.guideStep||0}, history=[], modal=null, toast=null, search='', savedLandmark='', savedState='', category='places', placeSearch='', reorder=false;
  const app=document.getElementById('app');
  function commit(edit) {
    const next=clone(state); edit(next);
    try { localStorage.setItem(KEY,JSON.stringify(next)); state=next; return true; }
    catch (_) { storageWarning=true; notify('Changes could not be saved. Check browser storage and try again.'); return false; }
  }
  const card = id => D.cards.find(x=>x.id===id);
  const area = id => D.areas.find(x=>x.id===id);
  const landmark = area;                      // 기존 호출부 호환
  const place = id => D.places.find(x=>x.id===id);
  // 지역(area)은 둘러보기 묶음일 뿐 일정의 목적지가 아니다. 목적지는 등록 장소와 출발지점이다.
  const destination = id => place(id)||(D.originPoints||[]).find(x=>x.id===id);
  const placesForCard = c => c ? D.placesForCard(c) : [];
  const typeOf = id => D.placeTypes.find(t=>t.id===id);
  const status = id => state.progress[id]||'new';
  // 카드는 단어 1개 = 1장이고 장소마다 복제하지 않는다.
  // 지역 → 그 지역 장소들의 유형 카드 / 장소 → 그 장소 유형의 카드 / Basics → 기초 카드
  function targetCards(id){
    if(id===D.basics.id) return D.cards.filter(c=>c.collectionId==='basics');
    const a=area(id); if(a){ const ids=new Set(D.places.filter(p=>p.areaId===id).flatMap(p=>D.cardsForPlace(p).map(c=>c.id))); return D.cards.filter(c=>ids.has(c.id)); }
    const p=place(id); if(p) return D.cardsForPlace(p);
    const c=card(id); return c?[c]:[];
  }
  // Basics는 장소가 없는 공공 표지판 묶음이다 (FR30). 지도·일정의 destination 후보가 아니다.
  const collection = id => id===D.basics.id ? D.basics : landmark(id);
  const isBasic = c => c?.kind==='basic';
  const paid = () => !!state.paid;
  const savedCount = () => Object.keys(state.saved).length;
  const atBookmarkLimit = () => !paid() && savedCount() >= FREE_BOOKMARK_LIMIT;
  // 유료 잠금(자물쇠, 탭 가능)과 Basics 미연결(버튼 자체 없음)은 서로 다른 상태다 (UX09).
  const lock = () => '<span class="lock" aria-hidden="true">🔒</span>';
  const trip = id => state.trips.find(t=>t.id===id);
  const countStatus = ids => ['new','learning','known'].map(s=>ids.filter(id=>status(id)===s).length);
  const icon = name => {
    const paths={explore:'<circle cx="12" cy="12" r="9"/><path d="m15.5 8.5-2 5-5 2 2-5z"/>',saved:'<path d="M6 3h12v18l-6-4-6 4z"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h2m4 0h2"/>',back:'<path d="m14 5-7 7 7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',pin:'<path d="M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',plus:'<path d="M12 5v14M5 12h14"/>',undo:'<path d="M4 10h10a6 6 0 0 1 0 12M4 10l5-5M4 10l5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',review:'<path d="M4 4h16v13H9l-5 4zM8 8h8m-8 4h5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',book:'<path d="M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3zM12 6v16"/>',left:'<path d="M20 12H4m6-6-6 6 6 6"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>'};
    return `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;
  };
  const button = (text, action, cls='btn-secondary', disabled=false) => `<button type="button" class="btn ${cls}" data-action="${esc(action)}" ${disabled?'disabled':''}>${text}</button>`;
  const image = (src,alt,cls='') => `<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`;
  // 기초 표지판은 사진이 아니라 앱이 그리는 표지판 판으로 보여준다.
  const signPlate = (c,cls='') => `<div class="${cls} sign-plate" role="img" aria-label="${esc(c.alt||c.word)}" style="--plate:${esc(c.color||'#2f6fb0')}"><span class="plate-group">${esc(c.groupLabel||'STREET SIGN')}</span><span class="plate-word" lang="ko">${esc(c.word)}</span><span class="plate-roman">${esc(c.roman||'')}</span></div>`;
  const cardVisual = (c,cls='') => c && isBasic(c) ? signPlate(c,cls) : image(c?.image,c?.alt||c?.word,cls);
  // FR29 발음 재생. 출시 버전은 사전 생성 TTS 파일을 번들하며, 이 프로토타입은 브라우저 음성합성으로 대신한다.
  const speakBtn = word => `<button type="button" class="btn btn-ghost speak-btn" data-action="speak:${esc(word)}" aria-label="Play pronunciation of ${esc(word)}">🔊 <span>Listen</span></button>`;
  function speak(text){
    try {
      if(!window.speechSynthesis){notify('Pronunciation audio is not available in this browser.');return;}
      speechSynthesis.cancel();
      const u=new SpeechSynthesisUtterance(text); u.lang='ko-KR'; u.rate=.8;
      u.onerror=()=>notify('Pronunciation audio is not available in this browser.');
      speechSynthesis.speak(u);
    } catch (_) { notify('Pronunciation audio is not available in this browser.'); }
  }
  // FR23 유료 잠금 → SC21. pending은 결제 성공 뒤 이어서 수행할 동작.
  function paywall(feature,pending=null){ navigate({name:'upgrade',feature,pending}); }
  const badge = text => `<span class="badge">${esc(text)}</span>`;
  const empty = (title,text,cta='') => `<div class="empty-state">${icon('book')}<h2>${esc(title)}</h2><p>${esc(text)}</p>${cta}</div>`;
  function notify(text, undo=null) { toast={text,undo}; renderToast(); clearTimeout(notify.timer); notify.timer=setTimeout(()=>{toast=null;renderToast();},10000); }
  function renderToast() { document.querySelector('.toast')?.remove(); if(toast) { const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.innerHTML=`<span>${esc(toast.text)}</span>${toast.undo?button('Undo','toast-undo','btn-ghost'):''}${button(icon('close'),'toast-close','icon-btn')}`;app.append(el); } }
  function navigate(next,replace=false) { if(!replace) history.push(clone(route));route=typeof next==='string'?{name:next}:next;modal=null;render();window.scrollTo(0,0); }
  function back() { modal=null;route=history.pop()||{name:'explore'};render(); }
  function sheet(title,body,actions,kind='',payload={}) { modal={title,body,actions,kind,payload,returnFocus:document.activeElement};renderModal(); }
  function confirm(title,text,onConfirm,label='Confirm') { sheet(title,`<p>${esc(text)}</p>`,button('Cancel','modal-close')+button(esc(label),'confirm','btn-primary'),'confirm',{onConfirm}); }
  function closeModal() { const focus=modal?.returnFocus;modal=null;document.querySelector('.modal-backdrop')?.remove();focus?.focus(); }
  function renderModal() { document.querySelector('.modal-backdrop')?.remove();if(!modal)return;const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(modal.title)}"><header class="sheet-head"><h2>${esc(modal.title)}</h2>${button(icon('close'),'modal-close','icon-btn')}</header><div class="sheet-body">${modal.body}</div><footer class="sheet-actions">${modal.actions}</footer></section>`;app.append(el);el.querySelector('button,input,select')?.focus(); }
  function header(title,subtitle='',eyebrow='SEOUL, SOUTH KOREA') { return `<div class="page-head"><p class="eyebrow">${esc(eyebrow)}</p><h1 class="page-title">${esc(title)}</h1>${subtitle?`<p class="page-subtitle">${esc(subtitle)}</p>`:''}</div>`; }
  function nav() { const active=['saved','plan','trip','tripForm','addPlaces'].includes(route.name)?(route.name==='saved'?'saved':'plan'):'explore';return ['explore','saved','plan'].map(n=>`<button class="nav-item ${active===n?'active':''}" data-action="tab:${n}">${icon(n)}<span>${n[0].toUpperCase()+n.slice(1)}</span>${n==='plan'&&!paid()?lock():''}</button>`).join(''); }
  function render() {
    const root=['explore','saved','plan'].includes(route.name), learn=route.name==='learn';
    app.innerHTML=`<div class="app-shell"><aside class="app-sidebar"><a class="brand" href="#" data-action="tab:explore"><span class="brand-mark">한</span><span>Sign Korean<small>READ. ROAM. REMEMBER.</small></span></a><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-note"><span class="badge">Interactive prototype</span><p>A little Korean.<br>A whole new Seoul.</p><small>English · Seoul collection</small></div>${button(icon('settings')+' Settings','settings','btn-ghost')}</aside><main class="workspace ${learn?'workspace-learning':''}"><header class="topbar"><div class="topbar-left">${root?'<span class="mobile-brand">한 <b>Sign Korean</b></span>':button(icon(route.name==='learn'?'close':'back'),route.name==='learn'?'leave':'back','icon-btn back-button')}<span class="topbar-caption">${root?'Your Seoul, one sign at a time':esc(screenTitle())}</span></div>${root?button(icon('settings'),'settings','icon-btn'):''}${learn?button(icon('undo')+' Undo','undo','btn-ghost',!state.session?.undo):''}</header><div class="page-body">${storageWarning?'<div class="notice">Browser storage is unavailable. Saved changes may not persist.</div>':''}${page()}</div>${root?`<nav class="bottom-nav" aria-label="Main navigation">${nav()}</nav>`:''}</main></div>`;
    renderModal();renderToast();bindGestures();
  }
  function screenTitle(){return ({guide:'Getting started',landmark:'Landmark collection',basics:'Everyday street signs',upgrade:'Unlock trip planning',learn:state.session?.source||'Practice',summary:'Practice summary',place:'Registered place',places:'Where to see this sign',reviews:'Place reviews',photo:'Sign photo',settings:'Settings',trip:'Your day in Seoul',tripForm:'Trip details',addPlaces:'Add a registered place',map:'Walking route'})[route.name]||'Sign Korean';}
  function page() { const pages={explore:explorePage,guide:guidePage,landmark:landmarkPage,basics:basicsPage,learn:learnPage,summary:summaryPage,place:placePage,places:placesPage,reviews:reviewsPage,photo:photoPage,saved:savedPage,settings:settingsPage,plan:planPage,tripForm:tripFormPage,trip:tripPage,addPlaces:addPlacesPage,map:mapPage,upgrade:upgradePage};return (pages[route.name]||explorePage)(); }
  function explorePage(){const items=D.landmarks.filter(l=>(l.name+' '+l.koName).toLowerCase().includes(search.trim().toLowerCase()));return header('Find a sign. Find your Seoul.','Real streets. Useful Korean. A journey you can read.')+`<div class="hero-panel"><div><span class="eyebrow">LEARN ALONG THE WAY</span><h2>Make the city<br>your classroom.</h2><p>Learn the signs you will actually see.<br>Then build the day around them.</p>${button('Explore the collection '+icon('arrow'),'scroll-collection','btn-primary')}</div><div class="hero-art"><span class="hangul-display">안녕<br>서울</span><span class="hero-caption">Hello, Seoul.</span></div></div><div class="search-field">${icon('search')}<input class="input" aria-label="Search areas" placeholder="Search areas" data-input="search" value="${esc(search)}">${search?button(icon('close'),'clear-search','icon-btn'):''}</div>${state.session&&!state.session.finished?`<div class="resume-banner"><div><strong>Pick up where you left off</strong><p>${esc(state.session.source)} · ${state.session.decisions.length}/10 decisions</p></div>${button('Resume practice '+icon('arrow'),'resume','btn-primary')}</div>`:''}<div class="section-head"><h2>Start with the basics</h2><span class="muted">No place needed</span></div>${(()=>{const bs=targetCards(D.basics.id),known=bs.filter(c=>status(c.id)==='known').length;return `<button class="basics-card" data-action="basics"><div class="basics-plates">${bs.slice(0,3).map(c=>signPlate(c,'mini')).join('')}</div><div class="landmark-info"><span class="eyebrow">00 / ${esc(D.basics.tag.toUpperCase())}</span><h2>${esc(D.basics.name)}</h2><p class="korean">${esc(D.basics.koName)}</p><p class="small muted">${esc(D.basics.description)}</p><div class="row"><span>${bs.length} signs</span><span>${known}/${bs.length} known ${icon('arrow')}</span></div></div></button>`;})()}<div class="section-head" id="collection"><h2>Seoul by area</h2><span class="muted">${items.length} places to begin</span></div><div class="landmark-grid">${items.map((l,i)=>{const cs=targetCards(l.id),ps=D.places.filter(p=>p.areaId===l.id);return `<button class="landmark-card" data-action="landmark:${l.id}">${l.image?image(l.image,l.name,'landmark-image'):`<div class="landmark-image area-tint" style="--plate:${esc(l.color||'#2f6f5e')}" role="img" aria-label="${esc(l.name)}"><span lang="ko">${esc(l.koName)}</span></div>`}<div class="landmark-info"><span class="eyebrow">0${i+1} / ${esc(l.tag||'SEOUL AREA')}</span><h2>${esc(l.name)}</h2><p class="korean">${esc(l.koName)}</p><div class="row"><span>${ps.length} places · ${cs.length} signs</span><span>${cs.filter(c=>status(c.id)==='known').length}/${cs.length} known ${icon('arrow')}</span></div></div></button>`;}).join('')}</div>${!items.length?empty('No areas found','Try an English or Korean name.',button('Clear search','clear-search')):''}<div class="editorial-note"><span>01 / LEARN</span><p>Read the signs before you arrive.<br>Feel more at home when you do.</p></div>`;}
  function guidePage(){const step=route.step||0;const slides=[['Read the city, one sign at a time.','You can already read a little Hangul. Now discover what the signs around Seoul mean.','한글'],['A swipe is all it takes.','Left: I know. Right: Learn again. Your own judgement guides what comes next.','← 알다 →'],['Your next stop starts here.','Swipe down for the shop’s reviews. Save a sign and add its place to your travel plan.','↓ 리뷰']];return `<div class="onboarding"><div class="section-head"><span class="brand">Sign Korean</span>${button(route.revisit?'Close':'Skip',route.revisit?'back':'finish-guide','btn-ghost')}</div><div class="guide-art">${esc(slides[step][2])}</div>${header(slides[step][0],slides[step][1],`STEP ${step+1} OF 3`)}<div class="guide-dots">${[0,1,2].map(i=>`<span class="${i===step?'active':''}"></span>`).join('')}</div><div class="row">${step?button('Back','guide-back'):''}${button(step===2?'Get started':'Next',step===2?'finish-guide':'guide-next','btn-primary')}</div></div>`;}
  function landmarkPage(){const l=landmark(route.id);if(!l)return empty('Landmark unavailable','Return to Explore.');const cs=targetCards(l.id),n=countStatus(cs.map(c=>c.id));return `<div class="detail-hero">${l.image?image(l.image,l.name):`<div class="area-tint hero-tint" style="--plate:${esc(l.color||'#2f6f5e')}" role="img" aria-label="${esc(l.name)}"><span lang="ko">${esc(l.koName)}</span></div>`}${badge(l.tag||'SEOUL AREA')}</div>`+header(l.name,l.koName,'AREA COLLECTION')+`<p class="detail-description">${esc(l.description)}</p><div class="stat-grid">${['New','Learn again','Known'].map((s,i)=>`<div class="stat-card"><strong>${n[i]}</strong><span>${s}</span></div>`).join('')}</div><div class="chips">${button('All cards','mode:all','chip '+(route.mode!=='review'?'active':''))}${button('Review','mode:review','chip '+(route.mode==='review'?'active':''),!n[1])}</div>${button('Start practice '+icon('arrow'),'start-landmark','btn-primary',!cs.length)}<div class="section-head"><h2>Places in this area</h2><span>${D.places.filter(p=>p.areaId===l.id).length} registered</span></div><p class="muted small">Each place carries the signs of its type. Add any of them to a travel day.</p><div class="place-list">${D.places.filter(p=>p.areaId===l.id).map(p=>placeRow(p,'place:'+p.id)).join('')}</div>`;}
  // SC03 Basics 모드 — 장소가 없으므로 Reviews·Map·Add to plan 진입점을 그리지 않는다 (FR31/UX09).
  function basicsPage(){
    const b=D.basics,cs=targetCards(b.id),n=countStatus(cs.map(c=>c.id));
    const groups=D.basicGroups.map(g=>({...g,cards:cs.filter(c=>c.groupId===g.id)})).filter(g=>g.cards.length);
    return `<div class="detail-hero basics-hero">${signPlate(cs[0],'hero-plate')}${badge('EVERYDAY SIGNS')}</div>`
      +header(b.name,b.koName,'NO PLACE NEEDED')
      +`<p class="detail-description">${esc(b.description)}</p>
      <div class="stat-grid">${['New','Learn again','Known'].map((s,i)=>`<div class="stat-card"><strong>${n[i]}</strong><span>${s}</span></div>`).join('')}</div>
      <div class="chips">${button('All cards','mode:all','chip '+(route.mode!=='review'?'active':''))}${button('Review','mode:review','chip '+(route.mode==='review'?'active':''),!n[1])}</div>
      ${button('Start practice '+icon('arrow'),'start-basics','btn-primary',!cs.length)}
      <div class="notice"><strong>These signs belong to the street, not to a shop.</strong><p>That is why there are no reviews, routes or trip buttons here. Bookmarks and pronunciation work just like everywhere else.</p></div>
      <div class="section-head"><h2>What you will learn</h2><span>${cs.length} of 100 planned</span></div>
      <div class="group-list">${groups.map(g=>`<article class="group-row" style="--plate:${esc(g.color)}"><div class="group-bar"></div><div><strong>${esc(g.label)}</strong><small>${g.cards.length} in this prototype · ${g.target} planned</small><div class="group-words">${g.cards.map(c=>`<button class="word-chip" data-action="start-card:${c.id}" lang="ko">${esc(c.word)}</button>`).join('')}</div></div></article>`).join('')}</div>
      <p class="muted small">Prototype sample. The specification plans 100 everyday signs across these six groups.</p>`;
  }
  function placeRow(p,action,trailing=''){const t=typeOf(p.type),n=targetCards(p.id).length;return `<div class="place-row"><button class="place-row-main" data-action="${esc(action)}"><span class="type-dot" style="--plate:${esc(t?.color||'#2f6f5e')}" aria-hidden="true"></span><span><strong>${esc(p.name)}${p.example?' '+badge('Example'):''}</strong><small lang="ko">${esc(p.koName||'')}</small><small>${esc(t?.label||'')} · ${n} signs</small></span></button>${trailing||icon('arrow')}</div>`;}
  function begin(ids,source,returnRoute,mode='all'){const eligible=[...new Set(ids)].filter(id=>card(id)&&(mode!=='review'||status(id)==='learning'));if(!eligible.length){notify('No cards to review yet.');return;}const run=()=>{if(commit(s=>{s.session={ids:[...new Set(ids)],queue:eligible.map(id=>({id,ready:0})),decisions:[],source,returnRoute:clone(returnRoute),mode,meaning:false,undo:null,finished:false};}))navigate('learn');};if(state.session&&!state.session.finished)confirm('Start new practice?','You have an unfinished session. Its learning progress will stay, but the remaining queue will be replaced.',run,'Start new');else run();}
  function sessionCard(){const s=state.session;if(!s||!s.queue.length)return null;return card(s.queue[0].id);}
  function learnPage(){const s=state.session,c=sessionCard();if(!s||!c)return summaryPage();const spots=placesForCard(c);return `<div class="learning-layout"><div class="study-progress"><span>${badge(s.mode==='review'?'Review':'All cards')} <span class="muted">${esc(s.source)}</span></span><strong>${s.decisions.length}<span class="muted"> / 10 decisions</span></strong></div><div class="progress-track"><span style="width:${s.decisions.length*10}%"></span></div><div class="learning-card"><div class="sign-photo" id="swipe-photo" role="button" tabindex="0" aria-label="${esc(c.alt||c.word)}. Tap to enlarge. Swipe left: I know. Right: learn again.${isBasic(c)?'':' Down: reviews.'}">${cardVisual(c,'sign-image')}<div class="photo-overlay"><span class="badge">${esc(c.groupLabel||'Seoul sign')}</span><span class="photo-zoom-hint">Tap to zoom ${icon('plus')}</span></div><div class="swipe-feedback" aria-live="polite"></div></div><button class="bookmark-floating icon-btn ${state.saved[c.id]?'active':''}" data-action="save:${c.id}" aria-label="${state.saved[c.id]?'Unsave sign':'Save sign'}" aria-pressed="${!!state.saved[c.id]}">${icon('saved')}</button><div class="word-panel"><p class="eyebrow">CAN YOU READ THIS SIGN?</p><h1 lang="ko">${esc(c.word)}</h1><div class="pronunciation">${c.roman?`<span class="roman">${esc(c.roman)}</span>`:''}${speakBtn(c.word)}</div>${s.meaning?`<div class="meaning"><h2>${esc(c.meaning)}</h2><p>${esc(c.note||'')}</p></div>`:button('Show meaning','meaning','btn-ghost')}</div></div><div class="learning-actions">${button(icon('left')+' I know','judge:known','btn-know')}${button('Learn again '+icon('arrow'),'judge:learning','btn-again')}</div><p class="gesture-hint">Swipe left to know · right to learn again${spots.length?' · down to see where this sign is':''}</p>${spots.length?`<div class="row auxiliary-actions">${button(icon('pin')+` Where to see this (${spots.length})`,'places:'+c.id,'btn-ghost')}</div>`:`<p class="muted small basics-note">${esc(c.groupLabel)} · a street sign, not a shop. It isn’t tied to a place you can visit.</p>`}</div>`;}
  function judge(value){const current=sessionCard();if(!current)return;const s=state.session;const snapshot={queue:clone(s.queue),decisions:clone(s.decisions),meaning:s.meaning,previous:state.progress[current.id]||null,cardId:current.id};if(commit(next=>{const ss=next.session;ss.undo=snapshot;ss.queue.shift();ss.decisions.push({id:current.id,value});next.progress[current.id]=value;if(value==='learning')ss.queue.push({id:current.id,ready:ss.decisions.length+3});ss.meaning=false;ss.finished=ss.decisions.length>=10||!ss.queue.length;const ready=ss.queue.findIndex(q=>q.ready<=ss.decisions.length);if(ready>0)ss.queue.unshift(...ss.queue.splice(ready,1));})) { if(state.session.finished)navigate('summary',true);else render(); } }
  function undo(){const u=state.session?.undo;if(!u)return;if(commit(s=>{Object.assign(s.session,{queue:u.queue,decisions:u.decisions,meaning:u.meaning,undo:null,finished:false});if(u.previous)s.progress[u.cardId]=u.previous;else delete s.progress[u.cardId];}))navigate('learn',true);}
  function summaryPage(){const s=state.session;if(!s)return empty('No practice yet','Explore a landmark to begin.',button('Explore signs','tab:explore','btn-primary'));const n=s.decisions.filter(d=>d.value==='known').length,again=s.decisions.length-n,review=s.ids.filter(id=>status(id)==='learning').length;return `<div class="summary-hero">${icon('check')}<p class="eyebrow">A LITTLE MORE AT HOME</p><h1>Nice work,<br>city explorer.</h1><p>${esc(s.source)} · ${s.finished?'Session complete':'Session ended'}</p></div><div class="stat-grid"><div class="stat-card"><strong>${n}</strong><span>I know decisions</span></div><div class="stat-card"><strong>${again}</strong><span>Learn again decisions</span></div><div class="stat-card"><strong>${new Set(s.decisions.map(d=>d.id)).size}</strong><span>Unique signs studied</span></div></div><p class="muted">This is your self-assessment, not a test score.</p><div class="summary-review"><h2>${review} signs to review</h2><p>Make them feel familiar, one more time.</p>${button('Review again','review-again','btn-primary',!review)}</div><div class="stack">${button('Practice all','practice-all')}${button(icon('undo')+' Undo last decision','undo','btn-ghost',!s.undo)}${button('Done','summary-done','btn-ghost')}</div>`;}
  // SC08 — 이 간판을 볼 수 있는 등록 장소 목록. 학습에서 여행 계획으로 넘어가는 지점이다.
  function placesPage(){
    const c=card(route.id);if(!c)return empty('Sign unavailable','Return to your practice.');
    const spots=placesForCard(c),t=typeOf(c.typeId);
    const byArea=D.areas.map(a=>({a,list:spots.filter(p=>p.areaId===a.id)})).filter(x=>x.list.length);
    return header('Where to see this sign',`${c.word} · ${c.meaning}`,'PLACES WITH THIS SIGN')
      +`<div class="sign-strip">${signPlate(c,'mini')}<div><strong lang="ko">${esc(c.word)}</strong><span class="roman">${esc(c.roman)}</span><small>${esc(t?.label||'')}</small></div>${speakBtn(c.word)}</div>
      <p class="muted small">${spots.length} registered ${spots.length===1?'place':'places'} where you can see <span lang="ko">${esc(c.word)}</span>. Compare them, then add one to a travel day.</p>
      ${byArea.map(({a,list})=>`<div class="section-head"><h2>${esc(a.name)}</h2><span class="muted" lang="ko">${esc(a.koName)}</span></div><div class="spot-grid">${list.map(spotCard).join('')}</div>`).join('')}
      ${!spots.length?empty('No registered places yet','This sign is not linked to a place in the collection.'):''}`;
  }
  // SC08 가게 정보 카드 — 가게 사진·리뷰·위치를 한눈에. 간판 사진 대신 장소 사진을 쓴다.
  // 장소 사진은 출시 시 TourAPI(공공누리 제1·3유형)에서 불러오며 오프라인 번들이 필요 없다.
  function spotCard(p){
    const t=typeOf(p.type),a=area(p.areaId),rs=D.reviews.filter(r=>r.placeId===p.id);
    const avg=rs.length?(rs.reduce((n,r)=>n+(r.rating||0),0)/rs.length).toFixed(1):null;
    return `<article class="spot-card">
      <button class="spot-photo" data-action="place:${p.id}" aria-label="Open ${esc(p.name)}">${p.photo?image(p.photo,p.name,'spot-img'):`<div class="area-tint spot-tint" style="--plate:${esc(t?.color||'#2f6f5e')}"><span lang="ko">${esc(p.koName)}</span></div><span class="photo-pending">Photo via TourAPI at launch</span>`}</button>
      <div class="spot-body">
        <h3><button class="link-btn" data-action="place:${p.id}">${esc(p.name)}</button>${p.example?' '+badge('Example'):''}</h3>
        <p class="muted small"><span lang="ko">${esc(p.koName)}</span> · ${esc(t?.label||'')}</p>
        <p class="spot-rating">${avg?`<span class="review-stars" aria-hidden="true">★</span> <strong>${avg}</strong> <span class="muted">· ${rs.length} sample review${rs.length>1?'s':''}</span>`:'<span class="muted">No reviews yet</span>'}</p>
        ${rs[0]?`<p class="spot-snippet">“${esc(rs[0].text)}”</p>`:''}
        <p class="muted small spot-address">${icon('pin')} <span>${esc(p.address)}<br>${esc(a?.name||'')}</span></p>
        <div class="row spot-actions">${button(icon('review')+' Reviews','reviews:'+p.id,'btn-ghost')}${button(icon('pin')+' Route'+(paid()?'':' '+lock()),'map:'+p.id,'btn-ghost')}${button(icon('plus')+' Add'+(paid()?'':' '+lock()),'add-plan:'+p.id,'btn-ghost')}</div>
      </div>
    </article>`;
  }
  function placePage(){const p=place(route.id);if(!p)return empty('Place unavailable','Return to your previous screen.');const cs=targetCards(p.id),c=card(route.cardId)||cs[0];const t=typeOf(p.type),rv=D.reviews.filter(r=>r.placeId===p.id).length;return header(p.name,p.koName,'REGISTERED PLACE')+`<p class="muted address">${icon('pin')} ${esc(p.address)}</p><div class="row place-meta"><span class="type-dot" style="--plate:${esc(t?.color||'#2f6f5e')}"></span><span>${esc(t?.label||'')}</span>${p.example?badge('Example place'):''}${rv?badge(rv+' reviews'):''}</div>${p.example?'<p class="muted small">A stand-in for this type of shop. Not a real business — the real collection comes from public data.</p>':''}${c?`<div class="learning-card detail-sign"><button class="sign-photo" data-action="photo:${c.id}">${cardVisual(c,'sign-image')}<span class="photo-zoom-hint">Tap to zoom ${icon('plus')}</span></button><div class="word-panel"><h1 lang="ko">${esc(c.word)}</h1><div class="pronunciation">${c.roman?`<span class="roman">${esc(c.roman)}</span>`:''}${speakBtn(c.word)}</div><h2>${esc(c.meaning)}</h2><p>${esc(c.note||'')}</p></div></div>${cs.length>1?`<div class="chips">${cs.map(x=>button(esc(x.word),'choose-card:'+x.id,'chip '+(x.id===c.id?'active':''))).join('')}</div>`:''}<div class="row">${button(icon('saved')+' '+(state.saved[c.id]?'Saved':'Save sign'),'save:'+c.id)}${badge(status(c.id)==='learning'?'Learn again':status(c.id))}</div>`:''}<div class="row detail-actions">${button(icon('review')+' Reviews','reviews:'+p.id)}${button(icon('pin')+' Map'+(paid()?'':' '+lock()),'map:'+p.id)}${button(icon('plus')+' Add to plan'+(paid()?'':' '+lock()),'add-plan:'+p.id)}</div>${button(`Practice these signs (${cs.length}) `+icon('arrow'),'start-place:'+p.id,'btn-primary',!cs.length)}`;}
  function reviewsPage(){const p=place(route.id),rs=D.reviews.filter(r=>r.placeId===route.id);return header(p?.name||'Place unavailable',p?.address||'','PLACE REVIEWS')+`<div class="notice"><strong>Sample reviews for this prototype</strong><p>Illustrative text, not live customer reviews or a provider rating.</p></div><div class="review-list">${rs.map(r=>`<article class="review-card"><div class="row"><div class="avatar">${esc((r.author||'Guest')[0])}</div><div><strong>${esc(r.author)}</strong><small class="muted">${esc(r.date)}</small></div><span class="review-stars" aria-label="${r.rating} out of 5">${'★'.repeat(r.rating||0)}</span></div><p class="review-text ${route.expanded?.includes(r.id)?'':'clamped'}">${esc(r.text)}</p>${button(route.expanded?.includes(r.id)?'Show less':'Read more','expand-review:'+r.id,'btn-ghost')}${r.translated?`<div class="translation-row">${badge('Sample translation')}${button(route.original?.includes(r.id)?'Hide original':'Show original','original-review:'+r.id,'btn-ghost')}</div>${route.original?.includes(r.id)?`<p class="original-review" lang="ko">${esc(r.original)}</p>`:''}`:''}</article>`).join('')}</div>${!rs.length?empty('No sample reviews yet','This place has no reviews in the demo collection.') :''}`;}
  function photoPage(){const c=card(route.id);return `<div class="photo-viewer"><div class="zoom-stage" id="zoom-stage">${cardVisual(c,'zoom-image')}</div><div class="row zoom-controls">${button('−','zoom-out')}${button('Reset zoom','zoom-reset')}${button('+','zoom-in')}</div><h2 lang="ko">${esc(c?.word)}</h2><div class="pronunciation">${c?.roman?`<span class="roman">${esc(c.roman)}</span>`:''}${c?speakBtn(c.word):''}</div><p class="muted small">Sign illustration: generated prototype asset. Landmark photo credits are in Settings.</p><p class="small muted">Double-click to zoom. Drag to pan; pinch on touch screens.</p></div>`;}
  function savedPage(){const ids=Object.keys(state.saved).sort((a,b)=>state.saved[b]-state.saved[a]);const cs=ids.map(card).filter(Boolean).filter(c=>(!savedLandmark||c.collectionId===savedLandmark||c.typeId===savedLandmark)&&(!savedState||status(c.id)===savedState));return header('Keep a little Seoul.','The signs and places you want to come back to.','YOUR SAVED SIGNS')+`${paid()?`<div class="quota-row paid">${badge('Unlocked')}<span>Unlimited bookmarks · ${ids.length} saved</span></div>`:`<div class="quota-row"><span><strong>${ids.length} of ${FREE_BOOKMARK_LIMIT}</strong> free bookmarks used</span>${button('Unlock unlimited','upgrade:bookmark','btn-ghost')}</div><div class="quota-track"><span style="width:${Math.min(100,ids.length/FREE_BOOKMARK_LIMIT*100)}%"></span></div>`}<div class="filter-row"><select class="select" data-input="saved-landmark" aria-label="Filter collection"><option value="">All sign types</option><option value="basics" ${savedLandmark==='basics'?'selected':''}>Everyday street signs</option>${D.placeTypes.map(t=>`<option value="${t.id}" ${savedLandmark===t.id?'selected':''}>${esc(t.label)}</option>`).join('')}</select><select class="select" data-input="saved-state" aria-label="Filter learning state">${[['','All states'],['new','New'],['learning','Learn again'],['known','Known']].map(([v,t])=>`<option value="${v}" ${v===savedState?'selected':''}>${t}</option>`).join('')}</select></div><div class="saved-list">${cs.map(c=>{const n=placesForCard(c).length;return `<article class="saved-row"><button class="saved-row-main" data-action="${n?'places:'+c.id:'start-card:'+c.id}">${cardVisual(c,'saved-thumb')}<span><strong lang="ko">${esc(c.word)}</strong><span>${esc(c.meaning)}</span><small>${esc(c.groupLabel)}${n?' · '+n+' places':' · no place'}</small>${badge(status(c.id)==='learning'?'Learn again':status(c.id))}</span></button><div class="row">${button(icon('saved')+' Unsave','unsave:'+c.id,'btn-ghost')}${n?button(icon('pin')+` Where to see this (${n})`,'places:'+c.id,'btn-ghost'):''}</div></article>`;}).join('')}</div>${!cs.length?empty(ids.length?'No saved signs match':'Save the signs you love.',ids.length?'Try clearing your filters.':'Tap the bookmark on any sign to keep it here.',button(ids.length?'Clear filters':'Explore signs',ids.length?'clear-filters':'tab:explore','btn-primary')):''}`;}
  function settingsPage(){return header('Make yourself at home.','A few things about this little travel companion.','SETTINGS')+`<div class="settings-list">${button(icon('book')+' Gesture guide','guide','settings-row')}<div class="settings-row"><span>Plan</span><strong>${paid()?'Unlocked · US$0.99 one-time':`Free · ${savedCount()}/${FREE_BOOKMARK_LIMIT} bookmarks`}</strong></div>${paid()?button('Lock again (prototype only)','relock','settings-row'):button('Unlock trip planning · US$0.99','upgrade:plan','settings-row')}${button('Restore purchase','restore','settings-row')}<div class="settings-row"><span>App language</span><strong>English</strong></div><div class="settings-row"><span>Location access</span><strong>Not requested by this prototype</strong></div>${button('Reset learning progress','reset-learning','settings-row')}${button('Clear saved signs','clear-saved','settings-row')}</div><details class="info-details"><summary>Pronunciation in this prototype</summary><p>The specification bundles pre-generated audio files so pronunciation works offline. This browser prototype uses the built-in speech synthesiser instead, so the voice and availability depend on your browser and operating system.</p></details><details class="info-details"><summary>Data on this device & privacy</summary><p>Learning progress, saved signs and trips are stored in this browser only. They are not sent to a server. Clearing browser storage removes them. This prototype does not request or collect your location.</p><p>External map links open a third-party site, whose privacy policy applies.</p></details><details class="info-details"><summary>Photos & credits</summary><p>Landmark photo credits are recorded in the accompanying asset manifest. Learning sign images are generated illustrations for prototype use. Reviews and walking durations are sample data. The route map is a schematic, not a navigation service.</p></details><p class="muted small">Sign Korean · Design prototype 1.0<br>Free MVP concept · Seoul collection</p>`;}
  // SC21 업그레이드 안내 (FR23~26)
  const PAID_FEATURES=[
    ['saved','Unlimited bookmarks','Keep every sign you want to come back to, not just five.'],
    ['pin','Walking routes & times','See the route, distance and estimated walking time to any sign’s place.'],
    ['plan','Day-by-day trip planner','Build your days, set stay times, and study the signs along tomorrow’s route.']
  ];
  const featureLead = f => f==='bookmark'?`You’ve saved ${FREE_BOOKMARK_LIMIT} of ${FREE_BOOKMARK_LIMIT} free signs.`:f==='map'?'Walking routes are part of the paid upgrade.':'Trip planning is part of the paid upgrade.';
  function upgradePanel(feature){
    return `<section class="upgrade-panel"><p class="eyebrow">UNLOCK TRIP PLANNING</p><h2>${esc(featureLead(feature))}</h2><ul class="upgrade-list">${PAID_FEATURES.map(([ic,t,d])=>`<li>${icon(ic)}<div><strong>${esc(t)}</strong><span>${esc(d)}</span></div></li>`).join('')}</ul><div class="upgrade-free"><strong>All signs, meanings, pronunciation and reviews stay free.</strong><span>Learning is never behind the paywall.</span></div><div class="upgrade-price"><strong>US$0.99</strong><span>One-time purchase · no subscription</span></div><div class="stack">${button('Unlock for US$0.99','purchase','btn-primary')}${button('Restore purchase','restore','btn-ghost')}</div><p class="muted small">Prototype: no real payment is taken. Unlocking is simulated on this device and can be undone in Settings.</p></section>`;
  }
  function upgradePage(){return header('Unlock trip planning','Keep learning for free. Add the travel tools when you need them.','UPGRADE')+upgradePanel(route.feature)+button('Not now','upgrade-dismiss','btn-ghost');}
  function planPage(){if(!paid())return header('A day worth wandering.','Build your route. Learn the signs before you go.','YOUR TRAVEL PLANS')+upgradePanel('plan');return header('A day worth wandering.','Build your route. Learn the signs before you go.','YOUR TRAVEL PLANS')+`<div class="section-head"><span>${state.trips.length} trips saved on this device</span>${button(icon('plus')+' Create trip','new-trip','btn-primary')}</div><div class="trip-list">${[...state.trips].sort((a,b)=>b.start.localeCompare(a.start)).map(t=>`<button class="trip-card" data-action="trip:${t.id}"><div class="trip-card-icon">${icon('plan')}</div><div><span class="eyebrow">${t.demo?'SAMPLE TRIP':'YOUR SEOUL TRIP'}</span><h2>${esc(t.title)}</h2><p>${dateLabel(t.start)} — ${dateLabel(t.end)}</p><small>${dates(t.start,t.end).length} days · ${Object.values(t.days).reduce((n,d)=>n+d.stops.length,0)} places</small></div>${icon('arrow')}</button>`).join('')}</div>${!state.trips.length?empty('Your Seoul story starts here.','Add registered landmarks and sign places to your days.',button('Try a sample day','sample-trip','btn-secondary')):''}<p class="storage-note">${icon('saved')} Saved on this device. No account needed.</p>`;}
  function tripFormPage(){const t=route.id?trip(route.id):null;const f=route.form||(route.form={title:t?.title||'',start:t?.start||today(),end:t?.end||today()});const ds=dates(f.start,f.end),valid=f.title.trim().length>=1&&f.title.trim().length<=40&&ds.length>=1&&ds.length<=14;return header(t?'Edit your trip.':'Where will Seoul take you?','Plan up to 14 days. Add places, then learn their signs.','TRIP DETAILS')+`<form id="trip-form" class="trip-form"><label class="field">Trip name<input class="input" name="title" data-input="trip-title" placeholder="My Seoul trip" maxlength="40" required value="${esc(f.title)}"><span class="small muted" id="title-count">${f.title.length}/40</span></label><div class="date-fields"><label class="field">Start date<input class="input" data-input="trip-start" type="date" name="start" required value="${esc(f.start)}"></label><label class="field">End date<input class="input" data-input="trip-end" type="date" name="end" required value="${esc(f.end)}"></label></div><p class="form-error" id="trip-error">${!ds.length?'End date must be on or after start date.':ds.length>14?'Trips can be up to 14 days.':!f.title.trim()?'Enter a trip name.':''}</p><p class="muted">Korea time (GMT+9) · Up to 14 days</p><div class="row">${button('Cancel','cancel-form')}${button(t?'Save changes':'Create trip','save-trip','btn-primary',!valid)}</div></form>`;}
  function timeString(minutes){return `${minutes>=1440?'Next day ':''}${String(Math.floor(minutes/60)%24).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;}
  function minutesBetween(a,b){if(!a||!b||![a.lat,a.lng,b.lat,b.lng].every(Number.isFinite))return null;if(a.id===b.id)return 0;const key=[a.id,b.id].sort().join('|');const found=D.routeMinutes?.[`${a.id}|${b.id}`]??D.routeMinutes?.[`${b.id}|${a.id}`]??D.routeMinutes?.[key];if(Number.isFinite(found))return found;const rad=v=>v*Math.PI/180;const km=Math.hypot((a.lat-b.lat)*111,(a.lng-b.lng)*111*Math.cos(rad(a.lat)));return Math.max(1,Math.round(km*1.3/4.2*60));}
  function dayCalc(day){let time=day.start.split(':').reduce((n,x,i)=>n+Number(x)*(i===0?60:1),0),travel=0,stay=0,prior=day.origin?destination(day.origin):null,valid=true;const rows=day.stops.map((s,i)=>{const dest=destination(s.destinationId),walk=prior?minutesBetween(prior,dest):i===0?0:null;if(walk===null||!dest)valid=false;if(valid){time+=walk;travel+=walk;}const arrival=valid?timeString(time):'—';stay+=s.stay;time+=s.stay;prior=dest;return {...s,dest,walk,arrival,leave:valid?timeString(time):'—'};});return {rows,travel,stay,total:travel+stay,finish:valid?timeString(time):'—',valid};}
  function activeTrip(){return trip(route.tripId||route.id);}
  function tripPage(){const t=activeTrip();if(!t)return empty('Trip unavailable','Go back to your plans.',button('Your plans','tab:plan'));const date=route.date||t.start,d=t.days[date],calc=dayCalc(d),ids=dayCards(d);return header(t.title,`${dateLabel(date)} · Korea time (GMT+9)`,t.demo?'SAMPLE TRIP':'YOUR TRAVEL DAY')+`<div class="row trip-tools">${button('Edit trip','edit-trip','btn-ghost')}${button('Delete trip','delete-trip','btn-ghost')}</div><div class="day-tabs chips">${dates(t.start,t.end).map((v,i)=>button(`Day ${i+1}<small>${dateLabel(v)}</small>`,'day:'+v,'chip '+(v===date?'active':''))).join('')}</div><div class="day-start"><div>${icon('pin')}<span><strong>${esc(d.start)} · ${esc(d.origin?destination(d.origin)?.name:'Start at first stop')}</strong><small>Walking · ${d.origin?'Includes travel to the first stop':'First-stop travel not included'}</small></span></div>${button('Edit','edit-start','btn-ghost')}</div><div class="section-head"><h2>Your places</h2>${button(reorder?'Done':'Reorder','reorder','btn-ghost',d.stops.length<2)}</div><div class="timeline">${calc.rows.map((s,i)=>`${s.walk?`<div class="travel-leg">${icon('pin')} Walking · ${s.walk} min <span class="muted">sample</span></div>`:''}<article class="timeline-stop"><span class="stop-number">${i+1}</span><div class="stop-content"><button class="stop-title" data-action="destination:${s.destinationId}"><strong>${esc(s.dest?.name||'Unavailable stop')}</strong><small lang="ko">${esc(s.dest?.koName||'')}</small></button><div class="stop-time">Arrive ${s.arrival} <span>→</span> Leave ${s.leave}</div><p class="small muted">Stay ${s.stay} min · ${targetCards(s.destinationId).length} signs</p>${reorder?`<div class="row">${button('↑ Move up','move-up:'+s.id,'btn-ghost',!i)}${button('↓ Move down','move-down:'+s.id,'btn-ghost',i===d.stops.length-1)}</div>`:''}</div>${button(icon('more'),'edit-stop:'+s.id,'icon-btn')}</article>`).join('')}</div>${!d.stops.length?empty('Room for a little discovery.','Add a landmark or a sign place to this day.') :''}${button(icon('plus')+' Add place','add-places','btn-secondary',d.stops.length>=10)}${d.stops.length>=10?'<p class="small muted">Maximum 10 places per day.</p>':''}${d.stops.length?`<div class="day-summary"><div class="section-head"><h2>Your day at a glance</h2>${badge('Sample walking times')}</div><div class="stat-grid"><div class="stat-card"><strong>${calc.valid?calc.travel:'—'}<small> min</small></strong><span>Travel</span></div><div class="stat-card"><strong>${calc.stay}<small> min</small></strong><span>Stay</span></div><div class="stat-card"><strong>${calc.valid?calc.total:'—'}<small> min</small></strong><span>Total</span></div></div><p>Finish around <strong>${calc.finish}</strong></p>${!calc.valid?'<p class="notice">Route incomplete. A registered destination is unavailable.</p>':''}</div>`:''}<div class="row day-actions">${button(icon('pin')+' View day route','day-map','btn-secondary',!d.stops.length||reorder)}${button(icon('book')+' Study this day','study-day','btn-primary',!ids.length||reorder)}</div><p class="muted small">Travel times are illustrative estimates. Confirm live directions before travelling.</p>`;}
  function dayCards(day){return [...new Set(day.stops.flatMap(s=>targetCards(s.destinationId).map(c=>c.id)))];}
  function addPlacesPage(){const t=trip(route.tripId),day=t?.days[route.date];if(!day)return empty('Day unavailable','Return to your plan.');const savedTypes=[...new Set(Object.keys(state.saved).map(id=>card(id)?.typeId).filter(Boolean))];let ps=category==='saved'?D.places.filter(p=>savedTypes.includes(p.type)):D.areas.some(a=>a.id===category)?D.places.filter(p=>p.areaId===category):D.places;ps=ps.filter(p=>(p.name+' '+p.koName).toLowerCase().includes(placeSearch.trim().toLowerCase()));return header('Make room for a new stop.',`${esc(t.title)} · ${dateLabel(route.date)}`,'REGISTERED PLACES ONLY')+`<div class="chips">${button('All places','category:places','chip '+(category==='places'?'active':''))}${button(`From saved signs (${savedTypes.length?D.places.filter(p=>savedTypes.includes(p.type)).length:0})`,'category:saved','chip '+(category==='saved'?'active':''),!savedTypes.length)}${D.areas.map(a=>button(esc(a.koName),'category:'+a.id,'chip '+(category===a.id?'active':''))).join('')}</div><div class="search-field">${icon('search')}<input class="input" data-input="place-search" placeholder="Search registered places" aria-label="Search registered places" value="${esc(placeSearch)}"></div><div class="place-list">${ps.map(p=>{const exists=day.stops.some(s=>s.destinationId===p.id);return placeRow(p,'destination:'+p.id,button(exists?'Already added':icon('plus')+' Add','insert:'+p.id,'btn-secondary',exists||day.stops.length>=10));}).join('')}</div>${!ps.length?empty('No registered places found','Try another category or search term.'):''}<p class="muted small">Add landmarks and sign places from the collection. Every new stop starts with a 30-minute stay.</p>`;}
  function addStop(tripId,date,id){const t=trip(tripId),day=t?.days[date];if(!destination(id)||!day)return false;if(day.stops.some(s=>s.destinationId===id)){notify('This place is already in this day.');return false;}if(day.stops.length>=10){notify('Maximum 10 places per day.');return false;}return commit(s=>s.trips.find(x=>x.id===tripId).days[date].stops.push({id:uid(),destinationId:id,stay:30}));}
  function addPlan(id){const selected=state.trips[0],selectedDate=selected?.start;openAddPlan(id,selected?.id,selectedDate);}
  function openAddPlan(id,tid,date){const t=trip(tid),day=t?.days[date],exists=day?.stops.some(s=>s.destinationId===id);sheet('Add to plan',`<p><strong>${esc(destination(id)?.name)}</strong><br><span class="muted">${esc(destination(id)?.address||'')}</span></p><label class="field">Choose trip<select class="select" data-input="add-trip"><option value="">Choose a trip</option>${state.trips.map(t=>`<option value="${t.id}" ${tid===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label>${t?`<label class="field">Choose day<select class="select" data-input="add-date">${dates(t.start,t.end).map(d=>`<option value="${d}" ${date===d?'selected':''}>${dateLabel(d)} · ${t.days[d].stops.length} places</option>`).join('')}</select></label>`:'<p class="muted">No trip selected. Create one to get started.</p>'}<p class="small muted">Stay: 30 min${exists?' · Already in this day':''}${day?.stops.length>=10?' · This day already has 10 places.':''}</p>`,button('Create trip','modal-new-trip','btn-ghost')+button(exists?'Already in this day':'Add place','modal-add','btn-primary',!day||exists||day.stops.length>=10),'addPlan',{id,tid,date});}
  function editStop(id){const t=activeTrip(),date=route.date||t.start,s=t.days[date].stops.find(s=>s.id===id);sheet('Edit stop',`<h3>${esc(destination(s.destinationId)?.name)}</h3><label class="field">Stay minutes<input class="input" data-input="stop-stay" type="number" min="0" max="480" step="1" value="${s.stay}" required></label><label class="field">Move to day<select class="select" data-input="stop-date">${dates(t.start,t.end).map(d=>`<option value="${d}" ${d===date?'selected':''}>${dateLabel(d)}</option>`).join('')}</select></label><p class="small muted">Moving to another day adds the stop at its end.</p><p class="form-error" id="stop-error"></p>`,button('Remove from day','remove-stop','btn-ghost')+button('Apply changes','apply-stop','btn-primary'),'editStop',{id,tid:t.id,originalDate:date,date,stay:s.stay,originalStay:s.stay});}
  function editStart(){const t=activeTrip(),date=route.date||t.start,d=t.days[date];sheet('Day start',`<p>${dateLabel(date)} · Korea time (GMT+9)</p><label class="field">Start time<input class="input" data-input="start-time" type="time" value="${esc(d.start)}" required></label><label class="field">Start at<select class="select" data-input="start-origin"><option value="">First stop</option>${allOrigins().map(p=>`<option value="${p.id}" ${d.origin===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><p class="small muted">First-stop travel is excluded when starting at the first stop. Registered start points are available offline.</p>${button('Use current location','location-info','btn-ghost')}`,button('Cancel','modal-close')+button('Apply','apply-start','btn-primary'),'start',{tid:t.id,date,start:d.start,origin:d.origin});}
  const allOrigins = () => [...D.places,...(D.originPoints||[])].filter((p,i,arr)=>arr.findIndex(x=>x.id===p.id)===i);
  function mapPage(){const dayMode=!!route.tripId,t=trip(route.tripId),d=dayMode?t?.days[route.date]:null,dest=dayMode?null:destination(route.id);const origin=destination(dayMode?d?.origin:route.origin),stops=dayMode?d.stops.map(s=>destination(s.destinationId)):dest?[dest]:[];const points=[...(origin?[origin]:[]),...stops].filter(Boolean),calc=dayMode?dayCalc(d):null,mins=dayMode?calc.travel:origin?minutesBetween(origin,dest):null;return header(dayMode?'Your day, on the map.':dest?.name||'Route',dayMode?`${t.title} · ${dateLabel(route.date)}`:'Plan a little walk through Seoul.','WALKING ROUTE')+`<div class="route-addresses"><div><span>FROM</span>${button(esc(origin?.name||(dayMode?'First stop':'Choose a start point')),dayMode?'map-edit-start':'map-origin','btn-ghost')}</div><div><span>TO</span><strong>${esc(dayMode?stops.map(p=>p?.name||'Unavailable').join(' → '):dest?.name||'Unavailable')}</strong></div></div><div class="map-canvas" id="map-stage">${mapSvg(points)}<div class="map-controls">${button('+','map-zoom-in','icon-btn')}${button('−','map-zoom-out','icon-btn')}${button('Fit','map-fit','icon-btn')}</div><span class="map-attribution">Schematic Seoul map · sample route, not navigation</span></div><div class="map-result"><div class="row">${icon('pin')}<div><span class="eyebrow">WALKING · SAMPLE ESTIMATE</span><h2>${mins===null?'—':mins+' min'}${dayMode?' travel':''}</h2></div></div>${mins===null?`<p>Choose a registered start point to see a sample walking time.</p>${button('Choose a start point','map-origin','btn-primary')}`:`<p>${dayMode?`Stay ${calc.stay} min · Total ${calc.total} min · Finish ${calc.finish}`:'Illustrative walking estimate. Check a live map before travelling.'}</p>`}${dayMode?`<div class="route-legs">${calc.rows.map((s,i)=>button(`${i+1}. ${esc(s.dest?.name||'Unavailable')} · ${s.walk===null?'—':s.walk} min`,'map-leg:'+i,'route-leg '+(route.leg===i?'active':''))).join('')}</div>`:''}<div class="row">${button('Refresh sample route','refresh-route')}${button('Open external map ↗','external-map')}</div>${dayMode?button('Edit day start / plan','map-edit-start','btn-ghost'):''}</div><p class="muted small">The line connects approximate registered coordinates. Map gestures and markers are interactive; this is not a live road route.</p>`;}
  function mapSvg(points){const all=allOrigins(),lats=all.map(p=>p.lat).filter(Number.isFinite),lngs=all.map(p=>p.lng).filter(Number.isFinite);const loLat=Math.min(...lats)-.008,hiLat=Math.max(...lats)+.008,loLng=Math.min(...lngs)-.008,hiLng=Math.max(...lngs)+.008;const xy=p=>[50+(p.lng-loLng)/(hiLng-loLng)*600,450-(p.lat-loLat)/(hiLat-loLat)*380];const routePoints=points.map(xy);return `<svg id="route-svg" viewBox="0 0 700 500" role="img" aria-label="Schematic route map with ${points.length} registered points"><rect width="700" height="500" fill="#e9eee4"/><g class="map-moving" id="map-moving"><path d="M-20 410Q130 360 230 420T470 410T740 450" stroke="#bdd5dc" stroke-width="48" fill="none"/><g stroke="#fffdf8" stroke-width="12" fill="none"><path d="M30 0 90 500M180 0 235 500M380 0 360 500M570 0 590 500M0 90 700 120M0 240 700 200M0 330 700 345"/><path d="M0 500 700 0M0 0 700 480"/></g><text x="28" y="470" fill="#6c909b" font-size="14">Han River · 한강</text><text x="285" y="170" fill="#9da695" font-size="26" letter-spacing="8">SEOUL</text>${D.places.map(p=>{const [x,y]=xy(p);return `<circle cx="${x}" cy="${y}" r="4" fill="#b7c3b0"/>`;}).join('')}${routePoints.length>1?`<polyline points="${routePoints.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#e27659" stroke-width="5" stroke-dasharray="9 5" stroke-linecap="round"/>`:''}${points.map((p,i)=>{const [x,y]=xy(p);return `<g tabindex="0" role="button" aria-label="${esc(p.name)}" data-action="map-marker:${p.id}" class="map-marker"><circle cx="${x}" cy="${y}" r="18" fill="${route.leg===i?'#e27659':'#254b42'}" stroke="white" stroke-width="3"/><text x="${x}" y="${y+5}" text-anchor="middle" fill="white" font-size="13" font-weight="bold">${i===0&&route.origin?'S':i+1}</text><rect x="${x-62}" y="${y+24}" width="124" height="24" rx="8" fill="white" opacity=".92"/><text x="${x}" y="${y+40}" text-anchor="middle" fill="#254b42" font-size="10">${esc(p.name)}</text></g>`;}).join('')}</g></svg>`;}
  function saveCard(id,undoAllowed=false){const old=state.saved[id];if(!old&&atBookmarkLimit()){paywall('bookmark','save:'+id);return;}if(commit(s=>{if(old)delete s.saved[id];else s.saved[id]=Date.now();})){render();notify(old?'Sign removed from Saved.':'Sign saved for your next visit.',old&&undoAllowed?()=>{if(commit(s=>s.saved[id]=old)){render();notify('Saved sign restored.');}}:null);}}
  function sampleTrip(){const date=today(),id=uid();if(commit(s=>s.trips.push({id,title:'A little Seoul discovery',start:date,end:date,demo:true,days:{[date]:{start:'09:00',origin:null,stops:[{id:uid(),destinationId:'gyeongbokgung',stay:60},{id:uid(),destinationId:'tongin',stay:30},{id:uid(),destinationId:'bukchon',stay:45}]}}})))navigate({name:'trip',tripId:id,date});}
  function saveTrip(){const f=route.form,ds=dates(f.start,f.end);if(!f.title.trim()||f.title.trim().length>40||!ds.length||ds.length>14)return;const existing=trip(route.id),outside=existing?Object.keys(existing.days).filter(d=>!ds.includes(d)&&existing.days[d].stops.length):[];const run=()=>{const id=existing?.id||uid();if(commit(s=>{const days=Object.fromEntries(ds.map(d=>[d,existing?.days[d]||makeDay()]));const value={id,title:f.title.trim(),start:f.start,end:f.end,days};if(existing)s.trips[s.trips.findIndex(t=>t.id===id)]=value;else s.trips.push(value);})){if(route.addContext){const context=route.addContext;back();openAddPlan(context.id,id,f.start);}else navigate({name:'trip',tripId:id,date:f.start},true);}};if(outside.length)confirm('Remove days outside the new dates?',outside.map(d=>`${dateLabel(d)}: ${existing.days[d].stops.length} places`).join('\n')+'\nThese days and their stops will be deleted.',run,'Delete listed days and save');else run();}
  function formChanged(){const t=trip(route.id),f=route.form;return t?f.title!==t.title||f.start!==t.start||f.end!==t.end:!!f.title||f.start!==today()||f.end!==today();}
  function cancelForm(){if(formChanged())confirm('Discard changes?','Your changes have not been saved.',back,'Discard');else back();}
  function startForDay(){const t=activeTrip(),date=route.date||t.start,ids=dayCards(t.days[date]),review=ids.filter(id=>status(id)==='learning').length;sheet('Study this day',`<p>${esc(t.title)} · ${dateLabel(date)}</p><p>${ids.length} unique signs along your route.</p>`,button('All cards','study-mode:all','btn-primary')+button(`Review (${review})`,'study-mode:review','btn-secondary',!review),'study',{ids,source:`${t.title} · ${dateLabel(date)}`,returnRoute:clone(route)});}
  function leave(){sheet('Leave practice?','<p>Your decisions are already saved. Keep the remaining signs for later, or end this session now.</p>',button('Cancel','modal-close')+button('Keep for later','keep-session','btn-primary')+button('End session','end-session','btn-ghost'),'leave');}
  app.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(el.getAttribute('href')==='#')e.preventDefault();dispatch(el.dataset.action);});
  function dispatch(action){const [a,...args]=action.split(':'),id=args[0];switch(a){
    case 'tab': modal=null;history=[];navigate(id,true);break;
    case 'back': if(route.name==='tripForm')cancelForm();else back();break;
    case 'settings':navigate('settings');break;
    case 'scroll-collection':document.getElementById('collection')?.scrollIntoView({behavior:'smooth'});break;
    case 'clear-search':search='';render();break;
    case 'landmark':navigate({name:'landmark',id,mode:'all'});break;
    case 'mode':route.mode=id;render();break;
    case 'guide':navigate({name:'guide',step:0,revisit:true});break;
    case 'guide-next':route.step++;if(!route.revisit)commit(s=>s.guideStep=route.step);render();break;
    case 'guide-back':route.step--;render();break;
    case 'finish-guide':if(route.revisit)back();else if(commit(s=>{s.onboard=true;s.guideStep=0;}))navigate('explore',true);break;
    case 'basics':navigate({name:'basics',mode:'all'});break;
    case 'start-basics':begin(targetCards(D.basics.id).map(c=>c.id),D.basics.name,route,route.mode||'all');break;
    case 'start-landmark':begin(targetCards(route.id).map(c=>c.id),landmark(route.id).name,route,route.mode||'all');break;
    case 'start-card':{const c=card(id);if(!c)break;begin([id],c.groupLabel,route);break;}
    case 'start-place':{const p=place(id);if(!p)break;begin(targetCards(p.id).map(c=>c.id),p.name,route,route.mode||'all');break;}
    case 'places':navigate({name:'places',id});break;
    case 'speak':speak(action.slice(action.indexOf(':')+1));break;
    case 'upgrade':paywall(id||'plan');break;
    case 'upgrade-dismiss':back();break;
    case 'purchase':{const fromUpgrade=route.name==='upgrade',pending=fromUpgrade?route.pending:null;if(commit(s=>{s.paid=true;s.everPaid=true;})){notify('Unlocked. Trip planning is now available.');if(fromUpgrade)back();else render();if(pending)dispatch(pending);}break;}
    case 'restore':{if(paid()){notify('Your purchase is already active.');break;}if(state.everPaid){if(commit(s=>s.paid=true)){render();notify('Purchase restored.');}}else notify('No previous purchase found.');break;}
    case 'relock':if(commit(s=>s.paid=false)){render();notify('Locked again. Use Restore purchase to unlock.');}break;
    case 'resume':navigate('learn');break;
    case 'meaning':if(commit(s=>s.session.meaning=true))render();break;
    case 'judge':judge(id);break;
    case 'undo':undo();break;
    case 'save':saveCard(id);break;
    case 'unsave':saveCard(id,true);break;
    case 'reviews':navigate({name:'reviews',id,expanded:[],original:[]});break;
    case 'expand-review':case 'original-review':{const key=a==='expand-review'?'expanded':'original';route[key]=route[key]||[];route[key]=route[key].includes(id)?route[key].filter(x=>x!==id):[...route[key],id];render();break;}
    case 'photo':navigate({name:'photo',id,zoom:1,panX:0,panY:0});break;
    case 'zoom-in':case 'zoom-out':case 'zoom-reset':route.zoom=a==='zoom-reset'?1:Math.max(1,Math.min(4,(route.zoom||1)+(a==='zoom-in'?.5:-.5)));if(route.zoom===1){route.panX=0;route.panY=0;}updateZoom();break;
    case 'place':navigate({name:'place',id});break;
    case 'place-card':navigate({name:'place',id,cardId:args[1]});break;
    case 'choose-card':route.cardId=id;render();break;
    case 'destination':navigate({name:'place',id});break;
    case 'clear-filters':savedLandmark='';savedState='';render();break;
    case 'leave':leave();break;
    case 'keep-session':{const rr=clone(state.session.returnRoute);closeModal();navigate(rr,true);break;}
    case 'end-session':if(commit(s=>s.session.finished=true))navigate('summary',true);break;
    case 'review-again':case 'practice-all':{const s=clone(state.session);begin(s.ids,s.source,s.returnRoute,a==='review-again'?'review':'all');break;}
    case 'summary-done':{const rr=clone(state.session.returnRoute);if(commit(s=>s.session=null))navigate(rr,true);break;}
    case 'modal-close':closeWithChanges();break;
    case 'confirm':{const fn=modal.payload.onConfirm;closeModal();fn();break;}
    case 'toast-undo':{const fn=toast?.undo;toast=null;fn?.();break;}
    case 'toast-close':toast=null;renderToast();break;
    case 'reset-learning':confirm('Reset learning progress?','Your learning states and practice session will be removed. Saved signs and trips stay.',()=>{if(commit(s=>{s.progress={};s.session=null;})){render();notify('Learning progress reset.');}},'Reset');break;
    case 'clear-saved':confirm('Clear saved signs?','All bookmarks will be removed. Learning progress and trips stay.',()=>{if(commit(s=>s.saved={})){render();notify('Saved signs cleared.');}},'Clear');break;
    case 'new-trip':navigate({name:'tripForm'});break;
    case 'modal-new-trip':{const context=modal.payload;closeModal();navigate({name:'tripForm',addContext:context});break;}
    case 'sample-trip':sampleTrip();break;
    case 'trip':navigate({name:'trip',tripId:id,date:trip(id).start});break;
    case 'edit-trip':navigate({name:'tripForm',id:activeTrip().id});break;
    case 'save-trip':saveTrip();break;
    case 'cancel-form':cancelForm();break;
    case 'delete-trip':{const t=activeTrip();confirm(`Delete ${t.title}?`,'This deletes this trip and its days. Saved signs and learning progress stay.',()=>{if(commit(s=>s.trips=s.trips.filter(x=>x.id!==t.id))){history=[];navigate('plan',true);notify('Trip deleted.');}},'Delete trip');break;}
    case 'day':route.date=id;reorder=false;render();break;
    case 'reorder':reorder=!reorder;render();break;
    case 'move-up':case 'move-down':{const t=activeTrip(),date=route.date||t.start;if(commit(s=>{const stops=s.trips.find(x=>x.id===t.id).days[date].stops,i=stops.findIndex(x=>x.id===id),j=i+(a==='move-up'?-1:1);if(j>=0&&j<stops.length)[stops[i],stops[j]]=[stops[j],stops[i]];}))render();break;}
    case 'add-places':{const t=activeTrip();placeSearch='';category='places';navigate({name:'addPlaces',tripId:t.id,date:route.date||t.start});break;}
    case 'category':category=id;render();break;
    case 'insert':if(addStop(route.tripId,route.date,id)){navigate({name:'trip',tripId:route.tripId,date:route.date},true);notify('Place added to your day.');}break;
    case 'add-plan':if(!paid()){paywall('plan',action);break;}addPlan(id);break;
    case 'modal-add':{const p=modal.payload;if(addStop(p.tid,p.date,p.id)){closeModal();render();notify('Added to '+trip(p.tid).title+' · '+dateLabel(p.date));}break;}
    case 'edit-stop':editStop(id);break;
    case 'apply-stop':applyStop();break;
    case 'remove-stop':{const p=modal.payload,s=trip(p.tid).days[p.originalDate].stops.find(x=>x.id===p.id);confirm('Remove '+destination(s.destinationId).name+'?','Only this visit will be removed. Saved signs and learning progress stay.',()=>{if(commit(s=>{const d=s.trips.find(t=>t.id===p.tid).days[p.originalDate];d.stops=d.stops.filter(x=>x.id!==p.id);})){render();notify('Stop removed.');}},'Remove');break;}
    case 'edit-start':editStart();break;
    case 'apply-start':{const p=modal.payload;if(!/^\d{2}:\d{2}$/.test(p.start))return;if(commit(s=>Object.assign(s.trips.find(t=>t.id===p.tid).days[p.date],{start:p.start,origin:p.origin||null}))){closeModal();render();notify('Day start updated.');}break;}
    case 'location-info':sheet('Use your location?','<p>The production app will request one-time access after your confirmation. This offline design prototype does not collect your location. Choose a registered start point instead.</p>',button('Choose a registered point','modal-close','btn-primary'),'location');break;
    case 'study-day':startForDay();break;
    case 'study-mode':{const p=modal.payload;closeModal();begin(p.ids,p.source,p.returnRoute,id);break;}
    case 'map':{if(!paid()){paywall('map',action);break;}const p=destination(id);navigate({name:'map',id,origin:p?.landmarkId||null,zoom:1,panX:0,panY:0});break;}
    case 'day-map':{const t=activeTrip();navigate({name:'map',tripId:t.id,date:route.date||t.start,zoom:1,panX:0,panY:0});break;}
    case 'map-origin':sheet('Choose a start point',`<p>Registered start points · offline collection</p><label class="field">Search registered places<input class="input" data-input="origin-search" placeholder="Name in English or Korean"></label><div id="origin-results">${originButtons('')}</div><p class="small muted">External address search requires a live map provider and is not connected in this prototype.</p>`,button('Cancel','modal-close'),'origin');break;
    case 'origin':route.origin=id;closeModal();render();break;
    case 'map-edit-start':if(route.tripId)navigate({name:'trip',tripId:route.tripId,date:route.date});else back();break;
    case 'map-leg':route.leg=Number(id);render();break;
    case 'map-marker':notify(destination(id)?.name||'Registered point');break;
    case 'map-zoom-in':case 'map-zoom-out':case 'map-fit':route.zoom=a==='map-fit'?1:Math.max(1,Math.min(3,(route.zoom||1)+(a==='map-zoom-in'?.3:-.3)));if(a==='map-fit'){route.panX=0;route.panY=0;}updateMap();break;
    case 'refresh-route':notify('Sample route refreshed. Live routing is not connected.');break;
    case 'external-map':{const dest=route.tripId?destination(trip(route.tripId).days[route.date].stops[route.leg||0]?.destinationId):destination(route.id);if(dest)window.open('https://map.kakao.com/link/map/'+encodeURIComponent(dest.name)+','+dest.lat+','+dest.lng,'_blank','noopener,noreferrer');break;}
  }}
  function originButtons(q){return allOrigins().filter(p=>(p.name+' '+p.koName).toLowerCase().includes(q.toLowerCase())).map(p=>button(icon('pin')+' '+esc(p.name),'origin:'+p.id,'origin-row')).join('')||'<p>No registered start points found.</p>';}
  function closeWithChanges(){if(modal?.kind==='editStop'){const p=modal.payload;if(p.stay!==p.originalStay||p.date!==p.originalDate){const old=modal;confirm('Discard changes?','Your stop edits have not been saved.',()=>{modal=null;render();},'Discard');modal.payload.keep=old;return;}}closeModal();}
  function applyStop(){const p=modal.payload,value=Number(p.stay),t=trip(p.tid),old=t.days[p.originalDate].stops.find(x=>x.id===p.id),target=t.days[p.date];let error='';if(p.stay===''||!Number.isInteger(value)||value<0||value>480)error='Enter a whole number from 0 to 480.';else if(p.date!==p.originalDate&&target.stops.some(x=>x.destinationId===old.destinationId))error='Place already added to this day.';else if(p.date!==p.originalDate&&target.stops.length>=10)error='Maximum 10 places per day.';if(error){document.getElementById('stop-error').textContent=error;return;}if(commit(s=>{const tt=s.trips.find(x=>x.id===p.tid),stop=tt.days[p.originalDate].stops.find(x=>x.id===p.id);stop.stay=value;if(p.date!==p.originalDate){tt.days[p.originalDate].stops=tt.days[p.originalDate].stops.filter(x=>x.id!==p.id);tt.days[p.date].stops.push(stop);}})){closeModal();route.date=p.date;render();notify('Stop updated.');}}
  app.addEventListener('input',e=>{const type=e.target.dataset.input,value=e.target.value;if(!type)return;switch(type){case 'search':search=value;rerenderKeepingInput(type);break;case 'place-search':placeSearch=value;rerenderKeepingInput(type);break;case 'trip-title':case 'trip-start':case 'trip-end':route.form[type.replace('trip-','')]=value;updateFormValidity();break;case 'stop-stay':modal.payload.stay=value;break;case 'start-time':modal.payload.start=value;break;case 'origin-search':document.getElementById('origin-results').innerHTML=originButtons(value);break;}});
  app.addEventListener('change',e=>{const type=e.target.dataset.input,value=e.target.value;switch(type){case 'saved-landmark':savedLandmark=value;render();break;case 'saved-state':savedState=value;render();break;case 'add-trip':openAddPlan(modal.payload.id,value,trip(value)?.start);break;case 'add-date':openAddPlan(modal.payload.id,modal.payload.tid,value);break;case 'stop-date':modal.payload.date=value;break;case 'start-origin':modal.payload.origin=value||null;break;}});
  app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='trip-form')saveTrip();});
  function updateFormValidity(){const f=route.form,ds=dates(f.start,f.end),valid=f.title.trim().length>0&&f.title.trim().length<=40&&ds.length>0&&ds.length<=14;document.querySelector('[data-action="save-trip"]').disabled=!valid;document.getElementById('title-count').textContent=f.title.length+'/40';document.getElementById('trip-error').textContent=!ds.length?'End date must be on or after start date.':ds.length>14?'Trips can be up to 14 days.':!f.title.trim()?'Enter a trip name.':'';}
  function rerenderKeepingInput(type){const el=document.querySelector(`[data-input="${type}"]`),pos=el?.selectionStart;render();const next=document.querySelector(`[data-input="${type}"]`);next?.focus();if(pos!=null)next?.setSelectionRange(pos,pos);}
  document.addEventListener('keydown',e=>{if(modal){const controls=[...document.querySelector('.sheet').querySelectorAll('button:not([disabled]),input,select,a[href]')];if(e.key==='Tab'&&controls.length){const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape')closeWithChanges();}else if(e.key==='Escape'){if(route.name==='learn')leave();else if(route.name==='tripForm')cancelForm();else if(!['explore','plan','saved'].includes(route.name))back();}});
  app.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeWithChanges();});
  function updateZoom(){const el=document.querySelector('.zoom-image');if(el)el.style.transform=`translate(${route.panX||0}px,${route.panY||0}px) scale(${route.zoom||1})`;}
  function updateMap(){const el=document.getElementById('map-moving');if(el)el.setAttribute('transform',`translate(${route.panX||0} ${route.panY||0}) translate(350 250) scale(${route.zoom||1}) translate(-350 -250)`);}
  function bindGestures(){const photo=document.getElementById('swipe-photo');if(photo){let start=null;photo.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY};photo.setPointerCapture(e.pointerId);});photo.addEventListener('pointermove',e=>{if(!start)return;const x=e.clientX-start.x,y=e.clientY-start.y;photo.style.transform=`translate(${x*.25}px,${y*.15}px) rotate(${x*.015}deg)`;const f=photo.querySelector('.swipe-feedback');f.textContent=Math.abs(x)>35&&Math.abs(x)>Math.abs(y)?x<0?'I KNOW':'LEARN AGAIN':y>40?'REVIEWS':'';f.className='swipe-feedback '+(x<0?'know':'again');});photo.addEventListener('pointercancel',()=>{start=null;photo.style.transform='';});photo.addEventListener('pointerup',e=>{if(!start)return;const x=e.clientX-start.x,y=e.clientY-start.y;start=null;photo.style.transform='';if(Math.abs(x)>65&&Math.abs(x)>Math.abs(y)*1.2)judge(x<0?'known':'learning');else if(y>75&&y>Math.abs(x)*1.2&&sessionCard()?.placeId)navigate({name:'reviews',id:sessionCard().placeId,expanded:[],original:[]});else if(Math.abs(x)<10&&Math.abs(y)<10)navigate({name:'photo',id:sessionCard().id,zoom:1,panX:0,panY:0});else photo.querySelector('.swipe-feedback').textContent='';});photo.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();navigate({name:'photo',id:sessionCard().id,zoom:1,panX:0,panY:0});}});}
    const zoom=document.getElementById('zoom-stage'),map=document.getElementById('map-stage');[zoom,map].filter(Boolean).forEach(el=>{let pointers=new Map(),start=null,pinch=null;const isMap=el===map,update=isMap?updateMap:updateZoom;el.addEventListener('pointerdown',e=>{if(e.target.closest('[data-action]'))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});el.setPointerCapture(e.pointerId);start={x:e.clientX,y:e.clientY,px:route.panX||0,py:route.panY||0};if(pointers.size===2){const [a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:route.zoom||1};}});el.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){const [a,b]=[...pointers.values()];route.zoom=Math.max(1,Math.min(isMap?3:4,pinch.zoom*Math.hypot(a.x-b.x,a.y-b.y)/pinch.distance));}else if(start&&(isMap||route.zoom>1)){route.panX=start.px+(e.clientX-start.x)*(isMap?700/el.clientWidth:1);route.panY=start.py+(e.clientY-start.y)*(isMap?500/el.clientHeight:1);}update();});const end=e=>{pointers.delete(e.pointerId);start=null;pinch=null;};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('dblclick',()=>{route.zoom=route.zoom>1?1:2;route.panX=0;route.panY=0;update();});});updateZoom();updateMap();
    document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.classList.add('image-unavailable');img.alt='Image unavailable. '+img.alt;const holder=img.closest('.sign-photo');if(holder&&!holder.querySelector('.image-error')){const hint=document.createElement('div');hint.className='image-error';hint.innerHTML='<p>Image unavailable</p>'+button('Retry photo','retry-image','btn-secondary');holder.append(hint);if(holder.id==='swipe-photo')document.querySelectorAll('[data-action^="judge:"]').forEach(b=>b.disabled=true);}}, {once:true}));
  }
  app.addEventListener('click',e=>{if(e.target.closest('[data-action="retry-image"]')){const holder=e.target.closest('.sign-photo'),img=holder.querySelector('img');holder.querySelector('.image-error')?.remove();img.classList.remove('image-unavailable');const src=img.src;img.src='';img.src=src;document.querySelectorAll('[data-action^="judge:"]').forEach(b=>b.disabled=false);}});
  window.SignKorean={navigate,getState:()=>clone(state),resetDemo:()=>{if(commit(s=>Object.assign(s,fresh()))){history=[];navigate({name:'guide',step:0},true);}}};
  render();
})();
